    __shared__ float sh[THREADS * 2];
    sh[threadIdx.x] = s;
    sh[threadIdx.x + THREADS] = ss;
    __syncthreads();
    for (int o = THREADS/2; o > 0; o >>= 1) {
        if (threadIdx.x < o) {
            sh[threadIdx.x] += sh[threadIdx.x + o];
            sh[threadIdx.x + THREADS] += sh[threadIdx.x + THREADS + o];
        }
        __syncthreads();
    }
    if (threadIdx.x == 0) {
        float total = sh[0];
        float total2 = sh[THREADS];
        float mean = total * invns;
        float var = total2 * invns - mean * mean;
        mr[row] = make_float2(mean, rsqrtf(var + 1e-5f));
    }
}

std::vector<torch::Tensor> ln_forward(torch::Tensor x, torch::Tensor w, torch::Tensor b, torch::Tensor ps, torch::Tensor mr, int64_t rows, int64_t ns, int64_t S, int64_t rpc) {
    auto y = torch::empty_like(x);
