    int pid = blockIdx.x;
    int row = pid / rpc;
    int rc = pid % rpc;
    float2 m = mr[row];
    float mean = m.x, rstd = m.y;
    long base = (long)row * ns4;
    long chunk = ns4 / rpc;
    long off = base + (long)rc * chunk;
    const float4* xp = x + off;
    const float4* wp = w + (long)rc * chunk;
    const float4* bp = b + (long)rc * chunk;
    float4* yp = y + off;
